package com.creatorhub.util; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; public class PasswordUtil { public static String sha256(String s){try{byte[] b=MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)); StringBuilder x=new StringBuilder(); for(byte v:b)x.append(String.format("%02x",v)); return x.toString();}catch(Exception e){throw new RuntimeException(e);}} }
